```python
from copy import deepcopy
from collections import UserDict

import pytest

from your_module import flatten_dict  # TODO: update this import


@pytest.mark.parametrize(
    ("data", "expected"),
    [
        ({}, {}),
        ({"a": 1, "b": 2}, {"a": 1, "b": 2}),
        ({"a": {"b": 1}, "c": 2}, {"a.b": 1, "c": 2}),
        (
            {"a": {"b": {"c": 1}}, "d": None, "e": False},
            {"a.b.c": 1, "d": None, "e": False},
        ),
        (
            {"a": {"list": [1, 2], "tuple": (3, 4)}, "none": None},
            {"a.list": [1, 2], "a.tuple": (3, 4), "none": None},
        ),
    ],
)
def test_flatten_dict_happy_paths(data, expected):
    assert flatten_dict(data) == expected


@pytest.mark.parametrize(
    ("sep", "expected"),
    [
        ("/", {"a/b/c": 1}),
        ("_", {"a_b_c": 1}),
        ("", {"abc": 1}),
    ],
)
def test_flatten_dict_custom_separator(sep, expected):
    data = {"a": {"b": {"c": 1}}}

    assert flatten_dict(data, sep=sep) == expected


def test_flatten_dict_with_parent_key():
    data = {"a": {"b": 1}, "c": 2}

    assert flatten_dict(data, parent_key="root") == {
        "root.a.b": 1,
        "root.c": 2,
    }


def test_flatten_dict_with_parent_key_and_custom_separator():
    data = {"a": {"b": 1}}

    assert flatten_dict(data, parent_key="root", sep="/") == {
        "root/a/b": 1,
    }


def test_empty_nested_dicts_are_omitted():
    data = {
        "a": {},
        "b": {"c": {}},
        "d": 3,
    }

    assert flatten_dict(data) == {"d": 3}


def test_original_dict_is_not_mutated():
    data = {"a": {"b": 1}, "c": [1, 2, 3]}
    before = deepcopy(data)

    result = flatten_dict(data)

    assert data == before
    assert result == {"a.b": 1, "c": [1, 2, 3]}


@pytest.mark.parametrize(
    ("data", "expected"),
    [
        ({"a": {"b": 1}, "a.b": 2}, {"a.b": 2}),
        ({"a.b": 2, "a": {"b": 1}}, {"a.b": 1}),
    ],
)
def test_key_collisions_last_value_wins(data, expected):
    assert flatten_dict(data) == expected


def test_dict_subclasses_are_flattened():
    class CustomDict(dict):
        pass

    data = {"a": CustomDict({"b": 1})}

    assert flatten_dict(data) == {"a.b": 1}


def test_non_dict_mapping_values_are_not_flattened():
    value = UserDict({"b": 1})
    data = {"a": value}

    result = flatten_dict(data)

    assert list(result.keys()) == ["a"]
    assert result["a"] is value


def test_non_string_keys_current_behavior():
    data = {
        1: "one",
        2: {"x": "two"},
    }

    assert flatten_dict(data) == {
        1: "one",
        "2.x": "two",
    }


@pytest.mark.parametrize(
    "bad_input",
    [
        None,
        [],
        (),
        "not a dict",
        42,
        object(),
    ],
)
def test_invalid_input_without_items_raises_attribute_error(bad_input):
    with pytest.raises(AttributeError, match="items"):
        flatten_dict(bad_input)


def test_cyclic_dict_raises_recursion_error():
    data = {}
    data["self"] = data

    with pytest.raises(RecursionError):
        flatten_dict(data)
